insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_130'
from (values
('127.879.d.1.A',3,'A collision-repair apprentice explains to a customer why a fender needs to be replaced rather than repaired, using plain words, and then records the decision on the work order. She is demonstrating:','["effective oral and written communication with individuals in the collision repair setting", "avoiding the customer", "skipping documentation", "unclear speaking"]'::jsonb,0,'Speak and write clearly.','original'),
('127.879.d.1.A',4,'When a customer is nervous about the cost of a repair, the best approach is to:','["rush the conversation", "explain the estimate item by item and answer questions calmly", "raise your voice", "avoid the question"]'::jsonb,1,'Clear explanation builds trust.','original'),
('127.879.d.1.B',3,'A student completes a repair order by listing panel damage, labor operations, paint codes and parts. She is using:','["vague notes", "random drawings", "technical writing skills to complete collision repair and refinish orders", "slang"]'::jsonb,2,'Precise work orders.','original'),
('127.879.d.1.B',4,'Which entry is the most useful on a collision repair order?','["''Fix car''", "''Do body stuff''", "''Paint it''", "''Replace left front fender; refinish and blend door''"]'::jsonb,3,'Specific operations.','original'),
('127.879.d.1.C',3,'A technician opens the paint manufacturer''s technical data sheet to find the mixing ratio and flash time for a clear coat. She is:','["locating and reading documents such as service and repair information and technical data sheets", "guessing", "ignoring data", "using memory only"]'::jsonb,0,'Read the TDS.','original'),
('127.879.d.1.C',4,'A technical data sheet gives the technician the product''s:','["color of the can", "mixing ratios, drying times and application guidelines", "maker''s address", "price history"]'::jsonb,1,'TDS content.','original'),
('127.879.d.2.A',3,'A student describes how a minor dent might be pulled and filled while a heavily buckled quarter panel may need to be sectioned or replaced. She understands:','["no repair types", "only one method", "the basic types of repair procedures used in collision repair", "paint only"]'::jsonb,2,'Repair or replace.','original'),
('127.879.d.2.A',4,'A panel that has been stretched and creased beyond repair limits is typically:','["painted over", "taped", "ignored", "replaced rather than repaired"]'::jsonb,3,'Beyond repair.','original'),
('127.879.d.2.B',3,'A student outlines the steps for refinishing: cleaning, sanding, priming, applying base and clear coat, and curing. She understands:','["the basic preparation, application and refinishing procedures", "random steps", "only the clear coat", "no steps"]'::jsonb,0,'Refinish steps.','original'),
('127.879.d.2.B',4,'Which step must come before spraying primer?','["buffing the clear coat", "sanding and cleaning the repaired area", "applying clear", "masking the wheels last"]'::jsonb,1,'Prep first.','original'),
('127.879.d.2.C',3,'An estimator adds 6 body-labor hours at $55, a $210 fender and 2.5 paint hours at $60. She is:','["ignoring cost", "avoiding math", "estimating parts and labor costs on a collision repair order", "guessing"]'::jsonb,2,'Estimate parts and labor.','original'),
('127.879.d.2.C',4,'Parts of $210 plus 4 hours of labor at $50 an hour equals a total of:','["$260", "$210", "$510", "$410"]'::jsonb,3,'210 + 200 = 410.','original'),
('127.879.d.3.A',3,'A student identifies a dual-action sander, a body hammer, a dolly and a spray gun on a tool board. She is identifying:','["hand and power tools and equipment commonly used in collision repair", "garden tools", "office tools", "kitchen tools"]'::jsonb,0,'Tool ID.','original'),
('127.879.d.3.A',4,'A dolly is used with a body hammer to:','["clean glass", "shape or smooth metal from the back side of a dent", "spray paint", "grind metal"]'::jsonb,1,'Hammer-and-dolly.','original'),
('127.879.d.3.B',3,'A student identifies MIG welding and plasma cutting as common processes for joining and cutting steel panels. She is identifying:','["a washing method", "a polishing method", "proper welding and cutting techniques and processes used in collision repair", "a paint process"]'::jsonb,2,'Welding and cutting.','original'),
('127.879.d.3.B',4,'Before welding near a fuel tank, a technician should:','["skip PPE", "ignore sparks", "weld faster", "remove or protect fuel-related components and have a fire extinguisher ready"]'::jsonb,3,'Fire safety.','original'),
('127.879.d.3.C',3,'A student labels solvents, isocyanate hardeners and used filters as hazardous and uses the correct storage and disposal. She is identifying:','["environmentally hazardous materials and appropriate handling and disposal", "water", "trash", "harmless materials"]'::jsonb,0,'Haz materials.','original'),
('127.879.d.3.C',4,'Isocyanates in some automotive clear coats require a technician to wear:','["a dust mask only", "a supplied-air or properly fitted respirator", "sunglasses only", "no mask"]'::jsonb,1,'Respiratory hazard.','original'),
('127.879.d.3.D',3,'A shop teaches students about aluminum-intensive bodies, adhesive bonding and driver-assist sensors. This shows awareness of:','["old methods only", "no change", "new and emerging collision repair and refinishing technologies", "a closed field"]'::jsonb,2,'New tech.','original'),
('127.879.d.3.D',4,'After a collision, a vehicle with a camera-based driver-assist system may need:','["a new radio", "only paint", "tire rotation", "sensor recalibration"]'::jsonb,3,'ADAS calibration.','original'),
('127.879.d.4.A',3,'A student checks the cord of a sander, wears eye and hearing protection and clamps a panel before grinding. She is demonstrating:','["the safe use of various hand and power tools and equipment", "careless habits", "ignoring rules", "unsafe practice"]'::jsonb,0,'Tool safety.','original'),
('127.879.d.4.A',4,'Before using a grinder, a technician should confirm that the:','["guard is removed", "guard is in place and the wheel has no cracks", "tool is plugged into a damaged cord", "wheel is wet"]'::jsonb,1,'Check guard and wheel.','original'),
('127.879.d.4.B',3,'A student identifies mild steel, high-strength steel, aluminum and carbon fiber panels on a car and the repair method each requires. She is identifying:','["tire types", "paint colors", "types of vehicle construction materials and associated repair methods", "radio types"]'::jsonb,2,'Materials and methods.','original'),
('127.879.d.4.B',4,'High-strength steel should not be repaired with excessive heat because it can:','["become lighter", "gain strength", "change color only", "lose its strength"]'::jsonb,3,'Heat weakens HSS.','original'),
('127.879.d.4.C',3,'A technician uses a dual-action sander with 80-grit paper to remove old paint from a dented door skin. She is:','["removing paint from the damaged area of a body panel", "painting", "adding paint", "washing the door"]'::jsonb,0,'Strip the paint.','original'),
('127.879.d.4.C',4,'Stripping the paint down to bare metal around a dent before repair is done so that:','["it adds weight", "the metal can be worked and the filler adheres properly", "it looks neat", "it saves sandpaper"]'::jsonb,1,'Proper adhesion.','original'),
('127.879.d.4.D',3,'A technician runs a hand over a repaired panel with a thin glove and uses a straightedge to find low and high spots. She is:','["guessing", "painting", "identifying and repairing surface irregularities on a damaged body panel", "ignoring dents"]'::jsonb,2,'Surface checking.','original'),
('127.879.d.4.D',4,'A high spot in a panel is usually corrected by:','["adding filler", "adding paint", "adding tape", "tapping it down with a hammer and dolly"]'::jsonb,3,'Low spots take filler, high spots get tapped.','original'),
('127.879.d.4.E',3,'A technician holds a dolly behind a dent and strikes the surrounding high area with a body hammer. She is demonstrating:','["hammer and dolly techniques for dent repair", "welding", "painting", "grinding"]'::jsonb,0,'On-dolly and off-dolly.','original'),
('127.879.d.4.E',4,'Striking directly over the dolly is called:','["hammer-off-dolly work", "hammer-on-dolly work, which stretches the metal", "painting", "masking"]'::jsonb,1,'On-dolly stretches metal.','original'),
('127.879.d.4.F',3,'A technician wipes a repair area with a wax-and-grease remover, then follows with a water-based cleaner before sanding. She is:','["avoiding prep", "painting", "preparing a damaged area using water-based and solvent-based cleaners", "guessing"]'::jsonb,2,'Clean first.','original'),
('127.879.d.4.F',4,'Wiping a surface with a clean cloth in one direction rather than scrubbing back and forth helps to:','["scratch the panel", "dry the cloth", "add contaminants", "lift contaminants instead of spreading them"]'::jsonb,3,'Clean technique.','original'),
('127.879.d.4.G',3,'A technician mixes body filler with a measured amount of hardener and spreads it on a scuffed panel with a spreader. She is:','["identifying, preparing and applying body filler", "guessing", "avoiding repair", "painting"]'::jsonb,0,'Body filler.','original'),
('127.879.d.4.G',4,'Too much hardener in body filler can cause:','["better curing", "pinholes, staining or poor adhesion", "shrinkage", "stronger repair"]'::jsonb,1,'Mix by spec.','original'),
('127.879.d.4.H',3,'A technician uses a block with 80-grit to shape filler, then follows with 180 and 320 grit before primer. She is:','["painting", "ignoring grit", "rough sanding body filler to contour the panel and finish sanding for the application", "guessing"]'::jsonb,2,'Progressive sanding.','original'),
('127.879.d.4.H',4,'A guide coat is used while sanding to:','["add color", "clean the panel", "dry the filler", "reveal high and low spots on the surface"]'::jsonb,3,'Guide coat.','original'),
('127.879.d.4.I',3,'A student prepares a panel and applies a primer-surfacer, then wet sands it before color. She is demonstrating:','["the proper preparation, application and refinishing of various types of primers", "washing the car", "welding", "polishing"]'::jsonb,0,'Primer.','original'),
('127.879.d.4.I',4,'A primer-surfacer is used mainly to:','["thin the paint", "fill small scratches and give the paint a uniform base", "cool the gun", "speed drying"]'::jsonb,1,'Primer function.','original'),
('127.879.d.4.J',3,'A student keeps the spray gun perpendicular to the panel, overlaps each pass by 50 percent and holds a steady distance. She is:','["avoiding technique", "painting by guess", "applying finish using appropriate spray techniques such as gun arc, angle and overlap", "spraying randomly"]'::jsonb,2,'Spray technique.','original'),
('127.879.d.4.J',4,'Tilting the spray gun at an angle at the end of each pass can cause:','["faster drying", "a perfect finish", "better coverage", "uneven thickness and streaking"]'::jsonb,3,'Keep the gun square.','original'),
('127.879.d.4.K',3,'A student sprays two coats of basecoat, waits the flash time, and finishes with two coats of clear. She is:','["applying basecoat and clear coat for overall refinishing", "washing", "sanding only", "polishing only"]'::jsonb,0,'Base and clear.','original'),
('127.879.d.4.K',4,'The clear coat is applied over the basecoat to:','["fill dents", "protect the color and give gloss", "speed drying", "remove color"]'::jsonb,1,'Clear protects.','original'),
('127.879.d.4.L',3,'After a new finish has cured, a student wet sands a dust nib with 1500 grit and polishes the area with a buffer. She is:','["stripping paint", "welding", "sanding, buffing and polishing a finish to remove defects", "painting"]'::jsonb,2,'Defect removal.','original'),
('127.879.d.4.L',4,'Buffing a finish too aggressively on a panel edge can:','["harden the paint", "add gloss", "fill scratches", "burn through the clear coat"]'::jsonb,3,'Careful on edges.','original'),
('127.880.d.1.A',3,'An estimator explains to an insurance adjuster why a bumper cover and its reinforcement bar must both be replaced, and notes the conversation in the file. She is applying:','["effective oral and written communication skills in collision repair", "poor writing", "avoiding talk", "unclear speech"]'::jsonb,0,'Communicate with others.','original'),
('127.880.d.1.A',4,'A collision shop supervisor tells an upset customer about a delay. The most effective approach is to:','["hide the problem", "give an honest update and a revised delivery date", "stop answering calls", "blame the customer"]'::jsonb,1,'Honest updates.','original'),
('127.880.d.1.B',3,'A technician writes on the repair order which panels were repaired, replaced or refinished, plus any supplements discovered during teardown. She is using:','["vague notes", "slang", "technical writing skills to complete collision repair orders and reports", "random drawings"]'::jsonb,2,'Document supplements.','original'),
('127.880.d.1.B',4,'A supplement to an estimate is needed when:','["the tires are new", "the car is washed", "the customer likes the color", "hidden damage is found after the car is disassembled"]'::jsonb,3,'Supplemental damage.','original'),
('127.880.d.1.C',3,'A technician looks up the OEM procedure for replacing a quarter panel and the sectioning locations allowed by the manufacturer. She is:','["locating, reading and interpreting service and repair information", "using memory only", "guessing", "ignoring procedures"]'::jsonb,0,'OEM procedures.','original'),
('127.880.d.1.C',4,'A repair should follow the vehicle manufacturer''s procedures because they:','["are cheaper", "preserve the vehicle''s crash performance and warranty", "are optional", "shorten paperwork"]'::jsonb,1,'OEM methods.','original'),
('127.880.d.1.D',3,'An estimator multiplies 3.5 body hours by $62 per hour and adds a $145 part, then applies a 6 percent sales tax to the part. She is:','["avoiding numbers", "ignoring tax", "applying mathematical skills to the estimating process", "guessing"]'::jsonb,2,'Estimating math.','original'),
('127.880.d.1.D',4,'If labor is 4 hours at $65 and parts are $300, the total before tax is:','["$365", "$260", "$460", "$560"]'::jsonb,3,'260 + 300 = 560.','original'),
('127.880.d.2.A',3,'A student explains when a non-structural panel can be repaired with hand tools and when a section needs to be cut out and replaced. She understands:','["the basic types of repair procedures for the collision repair industry", "only paint", "no repair types", "only welding"]'::jsonb,0,'Repair types.','original'),
('127.880.d.2.A',4,'A repair is generally preferred over replacement when the damage is:','["extreme", "minor and within the panel''s repair limits", "structural and kinked", "beyond repair"]'::jsonb,1,'Cost-effective repair.','original'),
('127.880.d.2.B',3,'Before repairs begin, a technician measures frame points and checks gaps and seams for hidden damage. She is performing:','["a paint job", "a sale", "a pre-repair inspection of non-structural and structural components", "a body wash"]'::jsonb,2,'Inspect first.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_130'
from (values
('127.880.d.2.B',4,'A pre-repair inspection is important because it:','["avoids paperwork", "delays the job", "adds cost only", "finds hidden damage that affects the repair plan"]'::jsonb,3,'Plan the repair.','original'),
('127.880.d.2.C',3,'A technician sands, primes and applies base and clear to a repaired door, then blends the color into the adjacent panel. She is demonstrating:','["the proper preparation, application and refinishing of various finishes", "stripping the paint", "welding the panel", "washing the car"]'::jsonb,0,'Refinish work.','original'),
('127.880.d.2.C',4,'Blending the new color into the neighboring panel is done to:','["use more paint", "avoid a visible color mismatch", "save clear coat", "speed drying"]'::jsonb,1,'Blend for match.','original'),
('127.880.d.2.D',3,'An estimator totals the labor operations and the parts on a collision job in an estimating system. She is:','["ignoring cost", "avoiding math", "estimating parts and labor costs of collision repair", "guessing"]'::jsonb,2,'Total the estimate.','original'),
('127.880.d.2.D',4,'A collision estimate typically lists parts, body labor, paint labor and:','["driver''s age", "the owner''s hobbies", "the day''s weather", "paint materials and sublet or other charges"]'::jsonb,3,'Complete estimate.','original'),
('127.880.d.2.E',3,'A technician uses a tram gauge and a three-dimensional measuring system to compare a unibody''s dimensions to the specification. She is:','["performing precision measurements to diagnose vehicle body shape and frame condition", "guessing", "painting", "ignoring specs"]'::jsonb,0,'Measure the body.','original'),
('127.880.d.2.E',4,'A unibody that measures out of specification at the strut tower indicates:','["perfect alignment", "structural damage that requires pulling or replacement", "a clean frame", "good paint"]'::jsonb,1,'Measure structure.','original'),
('127.880.d.3.A',3,'A student uses a pneumatic chisel, a body saw and a plastic welder as part of a collision repair project. She is using:','["garden tools", "kitchen tools", "hand and power tools and equipment commonly employed in collision repair", "office tools"]'::jsonb,2,'Tools of the trade.','original'),
('127.880.d.3.A',4,'A technician should inspect an air tool''s hose and fittings before use to prevent:','["tool noise", "tool weight", "tool shine", "hose whip and tool failure injuries"]'::jsonb,3,'Pre-use check.','original'),
('127.880.d.3.B',3,'A student compares squeeze-type resistance spot welding with MIG plug welding for joining panels on a late-model vehicle. She is identifying:','["proper welding and cutting techniques and processes in collision repair", "polishing", "washing", "painting"]'::jsonb,0,'Welding methods.','original'),
('127.880.d.3.B',4,'Following the vehicle maker''s welding procedure is important because heat can:','["improve every material", "change the properties of high-strength materials", "lighten the car", "cool the panel"]'::jsonb,1,'Heat effects.','original'),
('127.880.d.3.C',3,'A student collects used solvents, filters and paint waste in labeled containers for licensed disposal. She is:','["dumping them", "ignoring rules", "properly handling and disposing of environmentally hazardous materials", "using drains"]'::jsonb,2,'Hazmat disposal.','original'),
('127.880.d.3.C',4,'Used paint thinner should be disposed of by:','["pouring down the drain", "burning", "dumping on the ground", "a licensed waste hauler or approved recycler"]'::jsonb,3,'Regulated waste.','original'),
('127.880.d.3.D',3,'A technician studies how to repair carbon-fiber reinforced plastic parts and aluminum structures and how adhesives are used in new vehicles. She is demonstrating knowledge of:','["new and emerging collision repair technologies", "no change", "old equipment", "only paint"]'::jsonb,0,'Emerging repair tech.','original'),
('127.880.d.3.D',4,'Aluminum repair should be done in a separate area from steel repair to prevent:','["extra paint", "cross-contamination that causes galvanic corrosion", "speed", "noise"]'::jsonb,1,'Dedicated aluminum areas.','original'),
('127.880.d.4.A',3,'A technician checks the shop''s fire extinguishers, spray-booth filters and eyewash station on a schedule. She is:','["avoiding checks", "ignoring safety", "performing regular audits and inspections to maintain compliance with safety requirements", "decorating"]'::jsonb,2,'Safety audit.','original'),
('127.880.d.4.A',4,'A spray-booth''s airflow and filters must be checked regularly to:','["add paint", "reduce noise", "dry the floor", "protect workers from overspray and reduce fire risk"]'::jsonb,3,'Booth maintenance.','original'),
('127.880.d.4.B',3,'A student identifies a car''s steel, aluminum, magnesium and composite parts and how each is repaired. She is identifying:','["types of vehicle construction materials and associated repair methods", "tire types", "glass types", "paint types"]'::jsonb,0,'Materials ID.','original'),
('127.880.d.4.B',4,'Magnesium parts in a vehicle should be repaired carefully because the metal is:','["water soluble", "flammable when ground or heated", "too soft to touch", "magnetic"]'::jsonb,1,'Fire risk.','original'),
('127.880.d.4.C',3,'A student explains that a unibody''s crumple zones absorb crash energy and describes direct and indirect damage. She is identifying:','["paint methods", "tire types", "methods of collision energy management and types of damage", "glass types"]'::jsonb,2,'Crumple zones.','original'),
('127.880.d.4.C',4,'Crumple zones are designed to:','["stay rigid", "add weight", "reduce passenger room", "absorb crash energy by deforming progressively"]'::jsonb,3,'Energy absorption.','original'),
('127.880.d.4.D',3,'An estimator walks around a vehicle, measures gaps and lists damaged parts and operations in the estimating software. She is:','["determining vehicle damage and preparing an estimate of repair costs", "painting", "guessing", "washing the car"]'::jsonb,0,'Estimating.','original'),
('127.880.d.4.D',4,'Direct damage on a vehicle is damage:','["only to the paint", "at the point of impact", "only to glass", "at the opposite end"]'::jsonb,1,'Direct vs indirect.','original'),
('127.880.d.4.E',3,'A technician judges that a dented door skin can be repaired with hammer and dolly, while a creased roof panel must be replaced. She is determining:','["engine type", "paint color", "body panel damage and the associated repair methods", "tire size"]'::jsonb,2,'Repair vs replace.','original'),
('127.880.d.4.E',4,'A sharp crease that has stretched the metal beyond reasonable repair indicates the panel should be:','["ignored", "taped", "painted over", "replaced"]'::jsonb,3,'Stretched metal.','original'),
('127.880.d.4.F',3,'A technician removes the hood, hinges and fender bolts and re-hangs them, adjusting gaps with shims. She is:','["inspecting, removing, replacing and aligning body components such as hoods and fenders", "guessing", "washing", "painting"]'::jsonb,0,'Panel alignment.','original'),
('127.880.d.4.F',4,'Panel gaps are usually checked by comparing them:','["to a coin", "to the manufacturer''s specification or the opposite side", "to the tire size", "to the paint color"]'::jsonb,1,'Even gaps.','original'),
('127.880.d.4.G',3,'A student identifies a single-stage, a basecoat/clearcoat and a tri-coat finish, and the refinish method for each. She is identifying:','["glass types", "tire types", "types of vehicle finishes and associated refinish techniques", "engine types"]'::jsonb,2,'Finish types.','original'),
('127.880.d.4.G',4,'A tri-coat finish needs:','["no clear", "only a primer", "a single coat", "a basecoat, a mid-coat and a clear coat"]'::jsonb,3,'Three layers.','original'),
('127.880.d.4.H',3,'A technician removes a bolted fender, cuts a welded rocker section and bonds a new panel in place using the manufacturer''s procedure. She is:','["inspecting, removing and replacing bolted, bonded and welded panels", "washing", "guessing", "painting"]'::jsonb,0,'Panel types.','original'),
('127.880.d.4.H',4,'When replacing a bonded panel, the technician should:','["skip curing", "use the specified adhesive and cure time", "use any glue", "use tape"]'::jsonb,1,'Follow the adhesive spec.','original'),
('127.880.d.4.I',3,'A student identifies seat belts, pretensioners and airbags as parts of the occupant restraint system and how to repair them. She is identifying:','["tire systems", "paint systems", "vehicle occupant restraint systems and associated repair methods", "audio systems"]'::jsonb,2,'Restraint systems.','original'),
('127.880.d.4.I',4,'A seat belt that was in use during a collision should usually be:','["trimmed", "painted", "reused", "replaced, since it may be stretched or damaged"]'::jsonb,3,'Replace after crash.','original'),
('127.880.d.4.J',3,'A technician looks at a bent radiator support, damaged headlight mounts and a cracked bumper reinforcement. She is:','["identifying vehicle body components and assessing them for repair or replacement", "guessing", "washing", "painting"]'::jsonb,0,'Assess components.','original'),
('127.880.d.4.J',4,'The radiator support is part of the vehicle''s:','["glass", "front structure that supports the cooling components and front end parts", "roof", "rear bumper"]'::jsonb,1,'Support structure.','original'),
('127.880.d.4.K',3,'A student welds a patch panel with a MIG welder and cuts out damaged metal with a plasma cutter. She is demonstrating:','["washing", "painting", "the welding and cutting processes used in vehicle collision repair", "buffing"]'::jsonb,2,'Weld and cut.','original'),
('127.880.d.4.K',4,'Welding on a vehicle with electronic modules requires first:','["welding faster", "leaving the battery connected", "ignoring modules", "disconnecting the battery and protecting sensitive electronics"]'::jsonb,3,'Protect electronics.','original'),
('127.880.d.4.L',3,'A technician removes the front bumper, unplugs the fog lamps and reinstalls them once the repair is complete. She is:','["removing, installing and adjusting vehicle mechanical systems and electrical components", "guessing", "washing", "painting"]'::jsonb,0,'R&I.','original'),
('127.880.d.4.L',4,'After reinstalling a headlight, the technician should:','["leave it off", "check its operation and aim", "ignore it", "paint it"]'::jsonb,1,'Verify lighting.','original'),
('127.880.d.4.M',3,'A student examines a finish with cracks like a dried lakebed and traces it to a thick application without adequate flash time. She is:','["guessing", "painting", "identifying and determining the cause of paint and refinishing defects", "ignoring defects"]'::jsonb,2,'Defect diagnosis.','original'),
('127.880.d.4.M',4,'Dust nibs in a fresh clear coat are most often caused by:','["too much sun", "low humidity", "perfect cleaning", "contamination in the booth or on the surface"]'::jsonb,3,'Cleanliness.','original'),
('127.880.d.4.N',3,'A technician removes a side molding, replaces a broken trim clip and reinstalls the piece. She is discussing:','["interior and exterior trim repair", "paint repair", "engine repair", "tire repair"]'::jsonb,0,'Trim repair.','original'),
('127.880.d.4.N',4,'Trim clips should be replaced when broken because they:','["add color", "hold the trim securely and prevent rattles", "add weight", "cool the engine"]'::jsonb,1,'Clips secure trim.','original'),
('127.880.d.4.O',3,'A student describes how seam sealer, weld-through primer and cavity wax protect a repaired panel from rust. She is discussing:','["paint choices", "glass care", "corrosion protection, including sealers, adhesives and under-coatings", "tire care"]'::jsonb,2,'Corrosion protection.','original'),
('127.880.d.4.O',4,'After welding inside a closed section, a technician applies cavity wax to:','["speed drying", "add weight", "reduce noise", "protect the inner surface from rust"]'::jsonb,3,'Rust protection.','original'),
('127.880.d.4.P',3,'A technician cleans a panel with solvent, wipes it dry with a clean cloth and then cleans again with a water-based cleaner before priming. She is:','["preparing a damaged area using water-based and solvent-based cleaners", "painting", "avoiding prep", "guessing"]'::jsonb,0,'Two-step cleaning.','original'),
('127.880.d.4.P',4,'Why should a cleaner be wiped off before it evaporates?','["it saves cleaner", "so the dissolved contamination isn''t redeposited on the surface", "it smells better", "it dries the panel"]'::jsonb,1,'Wipe it off.','original'),
('127.880.d.4.Q',3,'A technician vacuums the interior, cleans the glass, polishes the paint and dresses the tires before returning the car. She is demonstrating:','["wheel alignment", "engine repair", "vehicle detailing", "body welding"]'::jsonb,2,'Detail the car.','original'),
('127.880.d.4.Q',4,'Detailing a vehicle after a repair is important mainly because it:','["avoids inspection", "adds weight", "lowers the price", "returns the car to the customer clean and shows professionalism"]'::jsonb,3,'Customer experience.','original'),
('127.880.d.4.R',3,'A technician cuts and fits new foam sound-deadening material into a repaired door cavity. She is:','["restoring sound deadeners and foam materials", "washing", "guessing", "painting"]'::jsonb,0,'Restore NVH materials.','original'),
('127.880.d.4.R',4,'Sound deadeners and foam in a body panel are used to:','["add weight only", "reduce noise and vibration inside the vehicle", "increase noise", "cool the metal"]'::jsonb,1,'NVH control.','original'),
('127.880.d.4.S',3,'A customer complains of water dripping from the headliner after a roof repair. The technician sprays water and checks seams to find the source. She is:','["painting", "guessing", "diagnosing and repairing water leaks, dust leaks and wind noise", "ignoring the leak"]'::jsonb,2,'Leak diagnosis.','original'),
('127.880.d.4.S',4,'A common cause of wind noise after a door adjustment is a:','["full tank", "new battery", "clean filter", "poorly aligned door or damaged weatherstrip"]'::jsonb,3,'Seal alignment.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
